'use strict';
const $=id=>document.getElementById(id);
const categoryNames={characters:'キャラクター',zones:'エリア',monsters:'モンスター',items:'アイテム・装備',skills:'スキル',nodes:'マップ地点',rarities:'レアリティ',materials:'素材',shops:'ショップ'};
const fieldNames={id:'固定ID',name:'名前',speed:'素早さ',hp:'HP',atk:'攻撃力',def:'守備力',wis:'賢さ',xp:'経験値',gold:'所持金・報酬',price:'価格',value:'補正値',cost:'消費MP',lv:'習得レベル',zoneId:'エリア',nodeId:'街の地点',itemIds:'販売商品',drops:'ドロップ素材',links:'接続先（双方向）',rarity:'レアリティ',bossId:'ボス',category:'分類',effects:'効果',desc:'説明',type:'種類',power:'倍率',base:'基礎値',shape:'姿',rate:'確率',x:'地図X',y:'地図Y',town:'街',boss:'ボス',common:'基本素材',bonusItemId:'装備ドロップ',travelMaterials:'道中の素材',party:'初期隊列',baseLuck:'うんのよさ（初期値）',luckPerLevel:'うんのよさ（レベル上昇分）',stats:'個別成長（省略時は既定値）',growth:'成長',travel:'道中',battle:'戦闘',inn:'宿屋',normalAttack:'通常攻撃',multiplier:'上昇倍率',turns:'継続ターン'};
let working=null,version=null,category='monsters',index=0,dirty=false;
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'content-type':'application/json'}}),result=await response.json();if(!response.ok)throw new Error(result.error||'接続できません');return result;}
const draft=()=>version?.status==='draft';
function changed(){dirty=true;$('versionInfo').textContent='未保存の変更があります。保存後にプレビュー・公開してください。';$('preview').disabled=true;$('publish').disabled=true;}
function reference(key){return {zoneId:'zones',nodeId:'nodes',bossId:'monsters',rarity:'rarities',common:'materials',bonusItemId:'items',links:'nodes',drops:'materials',itemIds:'items',travelMaterials:'materials',party:'characters'}[key];}
function drawList(){const filter=$('search').value.toLowerCase();$('entries').replaceChildren();working[category].forEach((entry,i)=>{if(filter&&!((entry.name||'')+' '+entry.id).toLowerCase().includes(filter))return;const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(i===index));button.textContent=entry.name||entry.id;const small=document.createElement('small');small.textContent=entry.id;button.append(small);button.onclick=()=>{index=i;drawList();drawEditor();};$('entries').append(button);});}
function field(key,value,parent,onchange){const label=document.createElement('label');label.textContent=fieldNames[key]||key;let control;const references=reference(key);
 if(references){control=document.createElement('select');control.multiple=Array.isArray(value);if(control.multiple)control.size=Math.min(6,Math.max(3,working[references].length));for(const row of working[references]){const option=document.createElement('option');option.value=row.id;option.textContent=(row.name||row.id)+' ('+row.id+')';option.selected=Array.isArray(value)?value.includes(row.id):value===row.id;control.append(option);}control.onchange=()=>{onchange(control.multiple?Array.from(control.selectedOptions,o=>o.value):control.value);changed();};}
 else if(typeof value==='boolean'){control=document.createElement('input');control.type='checkbox';control.checked=value;control.onchange=()=>{onchange(control.checked);changed();};}
 else if(typeof value==='number'||typeof value==='string'||value===null){control=document.createElement('input');control.type=typeof value==='number'||value===null?'number':'text';if(typeof value==='number')control.step='any';control.value=value??'';control.onchange=()=>{onchange(typeof value==='number'||value===null?(control.value===''?null:Number(control.value)):control.value);changed();if(key==='id'||key==='name')drawList();};}
 else{control=document.createElement('textarea');control.value=JSON.stringify(value,null,2);control.onchange=()=>{try{onchange(JSON.parse(control.value));control.setCustomValidity('');changed();}catch{control.setCustomValidity('正しいJSONを入力してください');control.reportValidity();}};label.className='wide';}
 control.disabled=!draft();control.dataset.field=key;label.append(control);parent.append(label);}
function drawEffects(entry,form){const container=document.createElement('section');container.className='wide';const heading=document.createElement('h3');heading.textContent='効果';container.append(heading);entry.effects.forEach((effect,i)=>{const row=document.createElement('div');row.className='effect';const select=document.createElement('select');select.setAttribute('aria-label','効果の種類');for(const type of GameContent.effectTypes){const option=document.createElement('option');option.value=type;option.textContent=type;select.append(option);}select.value=effect.type;select.disabled=!draft();select.onchange=()=>{const type=select.value;for(const key of ['power','base','amount','full','multiplier','turns'])delete effect[key];Object.assign(effect,type==='attackBuff'?{type,multiplier:1.5,turns:3}:['restoreHP','restoreMP'].includes(type)?{type,amount:45}:{type,power:1,base:0});changed();drawEditor();};row.append(select);for(const key of ['power','base','amount','full','multiplier','turns'])if(key in effect)field(key,effect[key],row,value=>effect[key]=value);const remove=document.createElement('button');remove.type='button';remove.textContent='この効果を削除';remove.disabled=!draft();remove.onclick=()=>{entry.effects.splice(i,1);changed();drawEditor();};row.append(remove);container.append(row);});const add=document.createElement('button');add.type='button';add.textContent='効果を追加';add.disabled=!draft();add.onclick=()=>{entry.effects.push({type:'magicDamage',power:1,base:0});changed();drawEditor();};container.append(add);form.append(container);}
function drawEditor(){const entry=working[category][index];$('editor').replaceChildren();$('editorTitle').textContent=entry?.name||entry?.id||'定義がありません';if(!entry)return;for(const [key,value]of Object.entries(category==='characters'?{stats:{},...entry}:entry)){if(key==='effects')drawEffects(entry,$('editor'));else field(key,value,$('editor'),next=>entry[key]=next);}}
function drawRules(){$('rulesEditor').replaceChildren();for(const [section,values]of Object.entries(working.rules)){if(Array.isArray(values)){field(section,values,$('rulesEditor'),value=>working.rules[section]=value);continue;}const group=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=fieldNames[section]||section;group.append(legend);for(const [key,value]of Object.entries(values))field(key,value,group,next=>values[key]=next);$('rulesEditor').append(group);}}
function draw(){drawRules();for(const id of ['save','add','duplicate','remove','label'])$(id).disabled=!draft();$('label').value=version.label;$('preview').disabled=dirty;$('publish').disabled=dirty;$('versionInfo').textContent=version.status==='draft'?'下書き · 更新番号 '+version.revision:'公開済みの定義は変更できません。下書きへ複製してください。';drawList();drawEditor();}
async function load(id){if(dirty&&!confirm('未保存の変更を破棄して読み込みますか？')){$('versions').value=version.id;return;}version=await api('/api/admin/versions/'+encodeURIComponent(id));working=structuredClone(version.data);dirty=false;index=0;draw();status('定義を読み込みました。');}
async function versions(selected){const result=await api('/api/admin/versions');$('versions').replaceChildren();for(const row of result.versions){const option=document.createElement('option');option.value=row.id;option.textContent=(row.id===result.activeId?'【現在の公開版】':row.status==='draft'?'【下書き】':'【公開済み】')+row.label;$('versions').append(option);}$('versions').value=selected||result.activeId;await load($('versions').value);}
function run(fn){return async()=>{try{await fn();}catch(error){status(error.message,true);}};}
$('versions').onchange=run(()=>load($('versions').value));$('category').onchange=()=>{category=$('category').value;index=0;drawList();drawEditor();};$('search').oninput=drawList;$('label').onchange=()=>{version.label=$('label').value;changed();};$('editor').onsubmit=event=>event.preventDefault();
$('create').onclick=run(async()=>{if(dirty&&!confirm('未保存の変更を破棄して新しい下書きを作りますか？'))return;const result=await api('/api/admin/drafts',{method:'POST',body:JSON.stringify({sourceId:version.id,label:version.label+' のコピー'})});dirty=false;await versions(result.id);status('下書きを作成しました。');});
$('save').onclick=run(async()=>{if(!draft())return;const errors=GameContent.validate(working);if(errors.length)throw new Error(errors.join('\n'));const result=await api('/api/admin/versions/'+version.id,{method:'PUT',body:JSON.stringify({data:working,label:$('label').value,revision:version.revision})});version.revision=result.revision;dirty=false;draw();status('下書きを保存しました。');});
$('validate').onclick=()=>{const errors=GameContent.validate(working);status(errors.length?errors.join('\n'):'検証に合格しました。ID・参照・マップ接続・効果を確認しました。',!!errors.length);};
$('preview').onclick=()=>{if(dirty)return;window.open('/?preview='+encodeURIComponent(version.id),'_blank','noopener');};
$('publish').onclick=run(async()=>{if(dirty||!confirm('この定義をゲームへ公開しますか？ 次回の読み込みから反映します。以前の公開版へ戻すこともできます。'))return;await api('/api/admin/versions/'+version.id+'/publish',{method:'POST',body:JSON.stringify({revision:version.revision})});await versions(version.id);status('公開版を切り替えました。ゲームを再読み込みすると反映されます。');});
$('export').onclick=()=>{const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(working,null,2)],{type:'application/json'}));link.download='game-content-'+version.id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);};
$('import').onchange=run(async()=>{const file=$('import').files[0];if(!file)return;if(file.size>2_000_000)throw new Error('ファイルが大きすぎます');const data=JSON.parse(await file.text()),errors=GameContent.validate(data);if(errors.length)throw new Error(errors.join('\n'));if(dirty&&!confirm('未保存の変更を破棄しますか？'))return;const result=await api('/api/admin/drafts',{method:'POST',body:JSON.stringify({data,label:file.name})});dirty=false;await versions(result.id);status('下書きとして取り込みました。公開前にプレビューしてください。');});
function add(copy){if(!draft())return;const sample=copy?working[category][index]:working[category][0];if(!sample)return;const entry=structuredClone(sample);let id=entry.id+'_copy';while(working[category].some(e=>e.id===id))id+='_1';entry.id=id;if(entry.name)entry.name+='（新規）';working[category].push(entry);index=working[category].length-1;changed();drawList();drawEditor();}
$('add').onclick=()=>add(false);$('duplicate').onclick=()=>add(true);
$('remove').onclick=()=>{if(!draft())return;const entry=working[category][index];if(!entry||!confirm((entry.name||entry.id)+'を削除しますか？'))return;const next=structuredClone(working);next[category].splice(index,1);const errors=GameContent.validate(next);if(errors.length){status('削除できません。参照先や必須の定義を確認してください。\n'+errors.join('\n'),true);return;}working=next;index=0;changed();drawList();drawEditor();};
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
for(const [key,name]of Object.entries(categoryNames)){const option=document.createElement('option');option.value=key;option.textContent=name;$('category').append(option);}$('category').value=category;
versions().catch(error=>status(error.message,true));
